from __future__ import annotations

import hashlib
import json
import re
import sys
from collections import Counter
from datetime import date, timedelta
from pathlib import Path

ROOT = Path('/Users/desmondchoy/Projects/twinkl')
sys.path.insert(0, str(ROOT))

from src.drift_review_app.data import load_review_data, MODEL_DIR, LOW_DIR
from src.drift_detector import detect_drift
from src.weekly_drift_reviewer import (
    WeeklyDriftReviewerDecision, WeeklyDriftReviewerEntry,
    WeeklyDriftReviewerRequest, WeeklyVerifierResponse,
    validate_weekly_drift_reviewer_response,
)
from src.wrangling.parse_wrangled_data import parse_wrangled_file


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_jsonl(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def week_start(day):
    d = date.fromisoformat(day)
    return d - timedelta(days=d.weekday())


def selected_ids(filename):
    return set(re.findall(r'^\| `([0-9a-f]{8})` \|', (ROOT / filename).read_text(), re.M))


known = selected_ids('docs/north_star/cohorts/known_drift_personas.md')
added = selected_ids('docs/north_star/cohorts/non_drift_personas.md')
selected = known | added
assert len(known) == 35 and len(added) == 70 and len(selected) == 105
report = {'selected_personas': len(selected), 'missing': {}, 'source_hashes': {}}
data = load_review_data(ROOT)
report['full_frozen_integrity'] = data.integrity
paths = [
    MODEL_DIR / 'prompts.jsonl', LOW_DIR / 'responses_gpt_5_6_luna_low.jsonl',
    MODEL_DIR / 'manifest.json', LOW_DIR / 'manifest.json',
    Path('config/evals/twinkl_52zz_model_comparison_v1.yaml'),
    Path('config/evals/twinkl_52zz_luna_low_v1.yaml'),
    Path('src/drift_detector.py'), Path('src/drift_review_app/data.py'),
    Path('src/weekly_drift_reviewer.py'), Path('prompts/weekly_vif_verifier.yaml'),
]
report['source_hashes'] = {str(p): digest(ROOT / p) for p in paths}
prompts = {
    (r['persona_id'], r['week_start']): r
    for r in read_jsonl(ROOT / MODEL_DIR / 'prompts.jsonl')
    if r['persona_id'] in selected
}
responses = {
    (r['persona_id'], r['week_start'], int(r['repeat'])): r
    for r in read_jsonl(ROOT / LOW_DIR / 'responses_gpt_5_6_luna_low.jsonl')
    if r['persona_id'] in selected
}
report['missing']['personas'] = sorted(selected - set(data.profiles))
expected = set()
span_empty = []
per_persona = []
source_counts = Counter()
raw_mismatches = []
source_files = {}
for pid in sorted(selected):
    profile, entries, warnings = parse_wrangled_file(ROOT / f'logs/wrangled/persona_{pid}.md')
    assert not warnings
    observed = {week_start(e['date']) for e in entries}
    for w in observed:
        expected.add((pid, w.isoformat()))
    span = set()
    cursor = min(observed)
    while cursor <= max(observed):
        span.add(cursor)
        cursor += timedelta(days=7)
    gaps = sorted(span - observed)
    span_empty.extend({'persona_id': pid, 'week_start': w.isoformat()} for w in gaps)
    source_counts['entries'] += len(entries)
    source_counts['responses'] += sum(bool(e['response_text']) for e in entries)
    source_counts['nudges'] += sum(bool(e['nudge_text']) for e in entries)
    source_counts['response_without_nudge'] += sum(bool(e['response_text']) and not e['nudge_text'] for e in entries)
    source_counts['sparse_final_week'] += max(e['date'] for e in entries) != (max(observed) + timedelta(days=6)).isoformat()
    raw_path = ROOT / f'logs/synthetic_data/persona_{pid}.md'
    raw = raw_path.read_text()
    source_files[str(raw_path.relative_to(ROOT))] = digest(raw_path)
    wrangled_path = ROOT / f'logs/wrangled/persona_{pid}.md'
    source_files[str(wrangled_path.relative_to(ROOT))] = digest(wrangled_path)
    for e in entries:
        for key in ('initial_entry', 'nudge_text', 'response_text'):
            if e[key] and e[key] not in raw:
                raw_mismatches.append({'persona_id': pid, 't_index': e['t_index'], 'field': key})
    per_persona.append({
        'persona_id': pid, 'cohort': 'known_drift' if pid in known else 'no_known_drift',
        'entries': len(entries), 'responses': sum(bool(e['response_text']) for e in entries),
        'observed_weeks': len(observed), 'span_weeks': len(span),
        'span_empty_weeks': [w.isoformat() for w in gaps],
        'entry_core_value_coordinates': len(entries) * len(profile['core_values']),
    })
report['source_inventory'] = dict(source_counts)
report['source_file_hashes'] = source_files
report['raw_source_mismatches'] = raw_mismatches
report['per_persona'] = per_persona
report['observed_weeks'] = len(expected)
report['span_weeks'] = sum(r['span_weeks'] for r in per_persona)
report['span_empty_weeks'] = span_empty
report['missing']['prompts'] = sorted(expected - set(prompts))
report['extra_prompts'] = sorted(set(prompts) - expected)
report['missing']['responses_by_run'] = {
    str(run): sorted((pid, w) for pid, w in expected if (pid, w, run) not in responses)
    for run in (1, 2, 3)
}
report['prompt_boundary_anomalies'] = []
report['historical_review_date_offsets_from_week_end'] = dict(Counter(str((date.fromisoformat(p['review_at_date']) - date.fromisoformat(p['week_end'])).days) for p in prompts.values()))
for (pid, ws), p in prompts.items():
    ws_d = date.fromisoformat(ws)
    if ws_d.weekday() != 0 or p['week_end'] != (ws_d + timedelta(days=6)).isoformat():
        report['prompt_boundary_anomalies'].append((pid, ws))

report['invalid_receipts'] = [
    {k: r.get(k) for k in ('persona_id', 'week_start', 'repeat', 'status', 'validation_error', 'attempts')}
    for r in responses.values() if r['status'] != 'ok'
]
report['receipt_statuses_by_run'] = {
    str(run): dict(Counter(r['status'] for (p,w,n), r in responses.items() if n == run))
    for run in (1, 2, 3)
}
report['decision_counts_by_run'] = {}
report['states_by_run'] = {}
report['current_v3_validation_failures'] = []
report['weekly_states'] = []
derived_results = {}
for run in (1, 2, 3):
    decisions_count = Counter()
    state_counts = Counter()
    for pid in sorted(selected):
        accumulated = []
        cases = data.cases_for_persona(pid)
        entries = {e.t_index: e for c in cases for e in c.entries}
        for boundary in data.boundaries_for_persona(pid):
            ws = boundary.week_start
            prompt = prompts[(pid, ws)]
            raw_response = responses[(pid, ws, run)]
            history = [
                WeeklyDriftReviewerEntry(t_index=int(i), date=entries[int(i)].date, text=t)
                for i, t in prompt['entry_text_by_t_index'].items()
            ]
            request = WeeklyDriftReviewerRequest(
                persona_id=pid, week_start=ws, week_end=boundary.week_end,
                core_values=list(boundary.declared_values), history=history,
                current_t_indices=list(boundary.current_t_indices),
                prompt=prompt['prompt'], prompt_sha256=prompt['prompt_sha256'],
                runtime_text_sha256=prompt['runtime_text_sha256'],
            )
            if raw_response['status'] == 'ok':
                try:
                    validate_weekly_drift_reviewer_response(
                        WeeklyVerifierResponse.model_validate(raw_response['parsed']), request
                    )
                except ValueError as error:
                    report['current_v3_validation_failures'].append({
                        'persona_id': pid, 'week_start': ws, 'run': run, 'reason': str(error),
                    })
            for case in cases:
                for i in boundary.current_t_indices:
                    d = data.decision('luna_low', run, case.case_id, i)
                    decisions_count['coordinates'] += 1
                    decisions_count[d.verdict if d.response_status == 'ok' else 'invalid_as_abstain'] += 1
                    accumulated.append(WeeklyDriftReviewerDecision(
                        persona_id=pid, week_start=ws, week_end=boundary.week_end,
                        t_index=i, date=entries[i].date, core_value=case.dimension,
                        verdict=d.verdict if d.response_status == 'ok' else 'abstain',
                        confidence=d.confidence if d.response_status == 'ok' else None,
                        reason_code=d.reason_code if d.response_status == 'ok' else None,
                        evidence_quote=d.evidence_quote if d.response_status == 'ok' else '',
                        review_status=d.response_status,
                    ))
            state = detect_drift(accumulated, persona_id=pid)
            derived_results[(pid, ws, run)] = state.model_dump(mode='json')
            state_counts[state.delivery_state] += 1
            state_counts[('known' if pid in known else 'added') + ':' + state.delivery_state] += 1
            report['weekly_states'].append({
                'persona_id':pid,'week_start':ws,'run':run,
                'state':state.delivery_state,'core_value_states':state.core_value_states,
                'drift_count':len(state.drifts), 'cutoff_t_index':state.cutoff_t_index,
            })
    report['decision_counts_by_run'][str(run)] = dict(decisions_count)
    report['states_by_run'][str(run)] = dict(state_counts)

report['existing_scenarios'] = []
report['saved_drift_output_mismatches'] = []
report['saved_drift_outputs_checked'] = 0
for path in (ROOT/'frontend/onboarding/public/scenarios').glob('*.json'):
    obj = json.loads(path.read_text())
    scenario = obj.get('scenario')
    if not isinstance(scenario,dict):
        continue
    pid = scenario.get('persona_id')
    if pid in selected:
        week_map = {w['week_id']: w['week_start'] for w in scenario['weeks']}
        for e in obj['trace_events']:
            if e['event_type'] != 'drift_detected':
                continue
            ws = week_map[e['result_refs'][0]['id']]
            report['saved_drift_outputs_checked'] += 1
            if e['details']['result'] != derived_results[(pid, ws, 1)]:
                report['saved_drift_output_mismatches'].append((pid, ws))
        report['existing_scenarios'].append({
            'path':str(path.relative_to(ROOT)), 'persona_id':pid,
            'weeks':len(scenario['weeks']), 'sha256':digest(path),
        })
output = Path('/tmp/nsm_upstream_audit.json')
output.write_text(json.dumps(report,indent=2,sort_keys=True)+'\n')
summary = {k:v for k,v in report.items() if k not in {
    'source_file_hashes','per_persona','weekly_states','full_frozen_integrity',
    'span_empty_weeks','source_hashes','current_v3_validation_failures',
}}
summary['span_empty_week_count'] = len(span_empty)
summary['personas_with_span_empty_weeks'] = sum(bool(r['span_empty_weeks']) for r in per_persona)
summary['current_v3_validation_failure_count'] = len(report['current_v3_validation_failures'])
summary['current_v3_failure_reasons'] = dict(Counter(r['reason'] for r in report['current_v3_validation_failures']))
print(json.dumps(summary, indent=2,sort_keys=True))
